package org.simpleweather.app;

import android.app.*;
import android.os.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.io.*;

/** Single-image grant; crop in local memory, flatten EXIF, save only after confirmation. */
public final class BackgroundCropActivity extends Activity {
    private CropView crop;
    private LinearLayout root;
    private TextView state;
    private boolean dead,saving;
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(12),dp(16),dp(12));root.setBackgroundColor(0xFFF5F7FB);root.setFitsSystemWindows(true);setContentView(root);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){Insets bars=insets.getInsets(WindowInsets.Type.systemBars());root.setPadding(dp(16)+bars.left,dp(12)+bars.top,dp(16)+bars.right,dp(12)+bars.bottom);}return insets;});state=new TextView(this);state.setText("正在读取图片…");state.setTextSize(16);root.addView(state);new Thread(()->{try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(getIntent().getData())){BitmapFactory.decodeStream(in,null,o);}if(o.outWidth<=0||o.outHeight<=0)throw new IOException();o.inSampleSize=1;while((long)(o.outWidth/o.inSampleSize)*(o.outHeight/o.inSampleSize)>6_000_000L||Math.max(o.outWidth,o.outHeight)/o.inSampleSize>3600)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap image;try(InputStream in=getContentResolver().openInputStream(getIntent().getData())){image=BitmapFactory.decodeStream(in,null,o);}if(image==null)throw new IOException();try(InputStream in=getContentResolver().openInputStream(getIntent().getData())){android.media.ExifInterface exif=new android.media.ExifInterface(in);int orientation=exif.getAttributeInt(android.media.ExifInterface.TAG_ORIENTATION,1);Matrix m=new Matrix();switch(orientation){case 2:m.setScale(-1,1);break;case 3:m.setRotate(180);break;case 4:m.setScale(1,-1);break;case 5:m.setRotate(90);m.postScale(-1,1);break;case 6:m.setRotate(90);break;case 7:m.setRotate(270);m.postScale(-1,1);break;case 8:m.setRotate(270);break;}if(!m.isIdentity()){Bitmap rotated=Bitmap.createBitmap(image,0,0,image.getWidth(),image.getHeight(),m,true);if(rotated!=image)image.recycle();image=rotated;}}catch(Exception ignored){}Bitmap finalImage=image;runOnUiThread(()->{if(!dead)ready(finalImage);});}catch(Exception|OutOfMemoryError e){runOnUiThread(()->{if(!dead){state.setText("无法读取图片，请返回换一张较小的图片。");button(root,"返回",()->finish());}});}}).start();}
    private void button(LinearLayout parent,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(14);GradientDrawable shape=new GradientDrawable();shape.setColor(0xFFEAF2FF);shape.setCornerRadius(dp(12));android.content.SharedPreferences p=getSharedPreferences("toolbox",0);if(p.getBoolean("outline",true))shape.setStroke(dp(1),p.getInt("outline_color",Color.BLACK));b.setBackground(shape);b.setOnClickListener(v->action.run());parent.addView(b,parent.getOrientation()==LinearLayout.VERTICAL?new LinearLayout.LayoutParams(-1,dp(48)):new LinearLayout.LayoutParams(0,dp(48),1));}
    private void ready(Bitmap bitmap){state.setText("调整背景使用区域");state.setTextSize(21);TextView help=new TextView(this);help.setText("拖动图片选取人物或区域，双指或滑块缩放。亮框内为保存范围。");help.setTextSize(13);help.setPadding(0,dp(8),0,dp(8));root.addView(help);float aspect=(float)getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().heightPixels;crop=new CropView(bitmap,aspect);root.addView(crop,new LinearLayout.LayoutParams(-1,0,1));SeekBar zoom=new SeekBar(this);zoom.setContentDescription("背景缩放");zoom.setMax(300);zoom.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){if(user)crop.setZoom(1+p/100f);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});crop.zoomChanged=z->zoom.setProgress(Math.round((z-1)*100));root.addView(zoom,new LinearLayout.LayoutParams(-1,dp(44)));LinearLayout actions=new LinearLayout(this);button(actions,"取消",()->finish());button(actions,"重置",()->crop.reset());button(actions,"使用选区",this::save);root.addView(actions);}
    private void save(){if(saving||crop==null)return;saving=true;state.setText("正在保存选区…");Bitmap selected;try{selected=crop.export();}catch(Exception|OutOfMemoryError e){saving=false;state.setText("选区保存失败，请缩小图片后重试");return;}new Thread(()->{try{File temp=new File(getFilesDir(),"background.tmp"),dest=new File(getFilesDir(),"background.jpg");try(FileOutputStream out=new FileOutputStream(temp)){if(!selected.compress(Bitmap.CompressFormat.JPEG,90,out))throw new IOException();}java.nio.file.Files.move(temp.toPath(),dest.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);runOnUiThread(()->{if(!dead){setResult(RESULT_OK);finish();}});}catch(Exception e){runOnUiThread(()->{if(!dead){saving=false;state.setText("保存失败，请重试");}});}finally{selected.recycle();}}).start();}
    @Override protected void onDestroy(){dead=true;super.onDestroy();}
    private final class CropView extends View {
        final Bitmap image;final float aspect;final Paint paint=new Paint(3);final RectF frame=new RectF();final ScaleGestureDetector scaleDetector;float zoom=1,base=1,x,y,lastX,lastY;java.util.function.Consumer<Float> zoomChanged;
        CropView(Bitmap image,float aspect){super(BackgroundCropActivity.this);this.image=image;this.aspect=aspect;setContentDescription("背景选区，拖动图片及双指缩放");scaleDetector=new ScaleGestureDetector(BackgroundCropActivity.this,new ScaleGestureDetector.SimpleOnScaleGestureListener(){@Override public boolean onScale(ScaleGestureDetector d){setZoom(zoom*d.getScaleFactor());if(zoomChanged!=null)zoomChanged.accept(zoom);return true;}});}
        @Override protected void onSizeChanged(int w,int h,int oldw,int oldh){float fw=Math.min(w-dp(24),(h-dp(24))*aspect),fh=fw/aspect;frame.set((w-fw)/2,(h-fh)/2,(w+fw)/2,(h+fh)/2);base=Math.max(fw/image.getWidth(),fh/image.getHeight());reset();}
        void reset(){zoom=1;x=frame.centerX()-image.getWidth()*base/2;y=frame.centerY()-image.getHeight()*base/2;if(zoomChanged!=null)zoomChanged.accept(zoom);invalidate();}
        void setZoom(float value){float next=Math.max(1,Math.min(4,value)),factor=next/zoom;x=frame.centerX()+(x-frame.centerX())*factor;y=frame.centerY()+(y-frame.centerY())*factor;zoom=next;clamp();invalidate();}
        void shift(float dx,float dy){x+=dx;y+=dy;clamp();invalidate();}
        void clamp(){x=Math.min(frame.left,Math.max(frame.right-image.getWidth()*base*zoom,x));y=Math.min(frame.top,Math.max(frame.bottom-image.getHeight()*base*zoom,y));}
        @Override protected void onDraw(Canvas c){c.drawColor(0xFF182334);float scale=base*zoom;c.drawBitmap(image,null,new RectF(x,y,x+image.getWidth()*scale,y+image.getHeight()*scale),paint);paint.setColor(0xAA000000);c.drawRect(0,0,getWidth(),frame.top,paint);c.drawRect(0,frame.bottom,getWidth(),getHeight(),paint);c.drawRect(0,frame.top,frame.left,frame.bottom,paint);c.drawRect(frame.right,frame.top,getWidth(),frame.bottom,paint);paint.setColor(Color.WHITE);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(dp(2));c.drawRect(frame,paint);paint.setStrokeWidth(dp(.5f));for(int i=1;i<3;i++){c.drawLine(frame.left+frame.width()*i/3,frame.top,frame.left+frame.width()*i/3,frame.bottom,paint);c.drawLine(frame.left,frame.top+frame.height()*i/3,frame.right,frame.top+frame.height()*i/3,paint);}paint.setStyle(Paint.Style.FILL);}
        @Override public boolean onTouchEvent(android.view.MotionEvent e){scaleDetector.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();return true;}if(e.getActionMasked()==MotionEvent.ACTION_POINTER_UP){int keep=e.getActionIndex()==0?1:0;lastX=e.getX(keep);lastY=e.getY(keep);return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){if(!scaleDetector.isInProgress()&&e.getPointerCount()==1)shift(e.getX()-lastX,e.getY()-lastY);lastX=e.getX();lastY=e.getY();return true;}return true;}
        Bitmap export(){int height=Math.min(2400,Math.max(1,Math.round(frame.height()/base/zoom))),width=Math.max(1,Math.round(height*aspect));Bitmap out=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);c.scale(width/frame.width(),height/frame.height());c.translate(-frame.left,-frame.top);float scale=base*zoom;c.drawBitmap(image,null,new RectF(x,y,x+image.getWidth()*scale,y+image.getHeight()*scale),new Paint(3));return out;}
    }
}
